def gen_placements(allow_rotate):
    pls=[]
    for pi,(h,w) in enumerate(piece_dims):
        dims={(h,w)}
        if allow_rotate and h!=w: dims.add((w,h))
        for hh,ww in sorted(dims):
            for r in range(H-hh+1):
                for c in range(W-ww+1):
                    cells=[(rr,cc) for rr in range(r,r+hh) for cc in range(c,c+ww)]
                    if all((rr,cc) in idx for rr,cc in cells):
                        b=sum(1<<idx[(rr,cc)] for rr,cc in cells)
                        pls.append((pi, r,c,hh,ww,b))
    return pls

def solve_rect(allow_rotate=False, limit=1, node_limit=1000000):
    pls=gen_placements(allow_rotate)
    by_piece=[[] for _ in pieces]
    by_cell=[[] for _ in target_cells]
    for p in pls:
        pi,r,c,hh,ww,b=p
        by_piece[pi].append(p)
        bits=b
        while bits:
            lb=bits & -bits; cell=lb.bit_length()-1
            by_cell[cell].append(p); bits-=lb
    # Pre-sort placements per cell by piece id; maybe order
    for li in by_cell: li.sort(key=lambda p:(p[3]*p[4],p[0],p[1],p[2]))
    allpieces=(1<<len(pieces))-1
    sols=[]; nodes=0
    def rec(occupied, remain, chosen):
        nonlocal nodes
        nodes+=1
        if nodes>node_limit or len(sols)>=limit: return
        if not remain:
            if occupied==allbits: sols.append(chosen.copy())
            return
        # choose uncovered cell with min viable candidate placements, among those considering piece available
        uncovered=allbits & ~occupied
        best=None; candbest=None; nbest=10**9
        bits=uncovered
        while bits:
            lb=bits & -bits; ci=lb.bit_length()-1
            cands=[]
            for p in by_cell[ci]:
                pi=p[0]
                if (remain>>pi)&1 and not (occupied & p[5]): cands.append(p)
            if len(cands)<nbest:
                best=ci; candbest=cands; nbest=len(cands)
                if nbest<=1: break
            bits-=lb
        if not candbest: return
        # prefer placements of larger area / constrain
        for p in candbest:
            pi=p[0]
            rec(occupied|p[5], remain&~(1<<pi), chosen+[p])
            if len(sols)>=limit or nodes>node_limit: return
    rec(0,allpieces,[])
    return sols,nodes,len(pls)
