def solve_shapes(target_mask, shapes, allow_rotate=False, limit=10,node_limit=2000000):
    HH,WW=target_mask.shape
    coords=[(r,c) for r in range(HH) for c in range(WW) if target_mask[r,c]]
    ix={p:i for i,p in enumerate(coords)}
    full=(1<<len(coords))-1
    placements=[]
    for pi,sh in enumerate(shapes):
        arr=np.array(sh,dtype=bool)
        variants=[arr]
        if allow_rotate:
            seen={arr.tobytes()}
            x=arr
            for _ in range(3):
                x=np.rot90(x)
                if x.tobytes() not in seen:
                    variants.append(x); seen.add(x.tobytes())
        for var in variants:
            hh,ww=var.shape
            shcoords=np.argwhere(var)
            for r in range(HH-hh+1):
                for c in range(WW-ww+1):
                    cells=[(r+int(dr),c+int(dc)) for dr,dc in shcoords]
                    if all(p in ix for p in cells):
                        bits=0
                        for p in cells: bits |= 1<<ix[p]
                        placements.append((pi,r,c,var,bits))
    npieces=len(shapes)
    bycell=[[] for _ in coords]
    for p in placements:
        bits=p[4]
        while bits:
            lb=bits&-bits; ci=lb.bit_length()-1
            bycell[ci].append(p);bits-=lb
    fullpieces=(1<<npieces)-1
    sols=[];nodes=0
    def rec(occ,rem,chosen):
        nonlocal nodes
        nodes+=1
        if nodes>node_limit or len(sols)>=limit:return
        if rem==0:
            if occ==full: sols.append(chosen.copy())
            return
        unc=full&~occ; best=None; cands=None; mn=10**9
        bits=unc
        while bits:
            lb=bits&-bits; ci=lb.bit_length()-1
            arr=[]
            for p in bycell[ci]:
                pi=p[0]
                if rem>>pi&1 and not occ&p[4]: arr.append(p)
            if len(arr)<mn:
                mn=len(arr);best=ci;cands=arr
                if mn<=1:break
            bits-=lb
        if not cands:return
        for p in cands:
            rec(occ|p[4],rem&~(1<<p[0]),chosen+[p])
            if len(sols)>=limit or nodes>node_limit:return
    rec(0,fullpieces,[])
    return sols,nodes
